["Collect 15 Partially Digested Journal Pages from the Shaper's Terrace."]="在塑造者露台收集 15 頁被部分消化的日記殘頁。",
["Enter Alcaz Prison and collect 8 Blood Red Bandanas from the human guards there."]="進入奧卡茲監獄，從人類守衛身上收集 8 條血紅頭巾。",
["Enter Alcaz Prison and learn what became of the King of Stormwind."]="進入奧卡茲監獄，查明暴風城國王的下落。",
["Enter Blackmaw Hold and recover 5 Blackmaw Pouches for Ekkal at the Ruins of Eldarath in Azshara."]="進入黑喉要塞，找回 5 個黑喉袋包，交給艾薩拉埃達拉斯廢墟的埃卡爾。",
["Enter the Alcaz Prison and find Commander Folkar."]="進入奧卡茲監獄，找到指揮官福爾卡。",
["Enter the Alcaz Prison and slay 15  Strashasz Soldiers, 8 Strashaz Enchantresses, and bring the head of Tidemistress Ca'zass to Sully McCleary."]="進入奧卡茲監獄，擊殺 15 名 Strashasz 士兵和 8 名 Strashaz 女妖術師，並將潮汐主母卡扎絲的頭顱交給薩莉·麥克利裡。",
["Enter the Alcaz Prison and slay 15 Strashasz Soldiers, 8 Strashaz Enchantresses, and bring the head of Tidemistress Ca'zass to Sergeant Ulka."]="進入奧卡茲監獄，擊殺 15 名 Strashasz 士兵和 8 名 Strashaz 女妖術師，並將潮汐主母卡扎絲的頭顱交給烏爾卡中士。",
["Find Interesting Landmarks in Shaper's Terrace and fill out the explorer's map at each."]="在塑造者露台尋找值得注意的地標，並在每處填寫探險者地圖。",
["Find the Totem of Ursoc and the Totem of Ursol inside Blackmaw Hold. Then, return them to Lorekeeper Nok at Ursolan."]="在黑喉要塞找到烏索克圖騰和烏索爾圖騰，將它們交還給烏索蘭的博學者諾克。",
["Gather 8 Seeping Slime Essence in the Shaper's Terrace."]="在塑造者露台收集 8 份滲出軟泥精華。",
["Gather a colorless Drained Crystal Fragment near the Achromatic Crystal in the Shaper's Terrace."]="在塑造者露台的無色水晶附近收集一塊無色的枯竭水晶碎片。",
["Look for King Varian Wrynn in Alcaz Prison."]="在奧卡茲監獄尋找瓦里安·烏瑞恩國王。",
["Recover the Alcaz Shackle Key from The Questioner in Alcaz Prison."]="從奧卡茲監獄的審問者身上取得奧卡茲鐐銬鑰匙。",
["Report to the Image of Archmage Modera near the City of Dalaran."]="向達拉然城附近的大法師莫德拉的影像報到。",
["Slay 6 Ravasaur Matriarchs, 9 Ironhide Ravasaurs and Venomridge in Shaper's Terrace."]="在塑造者露台擊殺 6 只暴掠龍母、9 只鐵皮暴掠龍和 Venomridge。",
["Speak to Archmage Celindra in the City of Dalaran."]="與達拉然城中的大法師塞琳德拉交談。",
["Travel to Blackmaw Hold in Kalimdor, and recover the Reliquary of Tyr."]="前往卡利姆多的黑喉要塞，取回提爾的聖物匣。",
