-- QuestieDB objective translations matched by quest ID and exact original text.
["Acquire 15 Winterspring Blood Samples and 20 gold and bring them along with a set of Wildheart Bracers to Deliana in Ironforge."]="將15份冬泉谷血樣、20枚金幣以及壹副野性之心護腕交給鐵爐堡的德莉亞娜。",
["Acquire 4 Healthy Courser Glands and bring them to Ogtinc in Azshara. Ogtinc resides atop the cliffs northeast the Ruins of Eldarath."]="收集4份健康的野鹿腺體，把它們交給艾薩拉的奧汀克。奧汀克住在埃達拉斯廢墟東北部懸崖的頂部。",
["Acquire an Ichor of Undeath for Ogtinc in Azshara. Ogtinc resides atop the cliffs northeast the Ruins of Eldarath."]="為艾薩拉的奧汀克帶回壹份亡靈腐液。奧汀克住在埃達拉斯廢墟東北部懸崖的頂端。",
["Acquire the reagents Ghak Healtouch needs from the Badlands, then return to him in Thelsamar."]="從荒蕪之地拿到加克所需的材料，然後回到塞爾薩瑪去見他。",
["Andrew Brownell wants you to kill Amnennar the Coldbringer and return his skull."]="安德魯·布隆奈爾要妳殺了寒冰之王亞門納爾並將其頭骨帶回來。",
["Answer Braug Dimspirit's question successfully and then speak to him again. He will remain in Stonetalon Mountains when you are ready."]="成功回答布勞格·幽魂的問題，然後和他再次對話。他會壹直在石爪山等妳回答問題。",
["Answer Parqual Fintallas' question successfully and then speak to him again. He will remain in the Undercity until you are ready."]="成功回答帕科瓦·芬塔拉斯的問題，然後再次和他對話。他會壹直在幽暗城等妳回答問題。",
["Apothecary Zamah in Thunder Bluff wants you to collect 10 Serpentbloom."]="為雷霆崖的藥劑師紮瑪收集10朵毒蛇花。",
["Archbishop Bendictus wants you to slay Amnennar the Coldbringer in Razorfen Downs."]="大主教本尼迪塔斯要妳去殺死剃刀高地的寒冰之王亞門納爾。",
["Bring 1 pile of Kraul Guano to Master Apothecary Faranell in the Undercity."]="幫幽暗城的大藥劑師法拉尼爾帶回壹堆沼澤蝙蝠的糞便。",
["Bring 10 Elixirs of Shadow Power to Gorzeeki Wildeyes in the Burning Steppes."]="把10瓶暗影之力藥劑交給燃燒平原的戈瑟奇·邪眼。",
["Bring 10 Encoded Fragments to Archmage Xylem in Azshara."]="將10塊密文碎片交給艾薩拉的大法師克希雷姆。",
["Bring 10 Glittering Dust to Archmage Xylem."]="為大法師克希雷姆收集10份閃光塵埃。",
["Bring 10 Rotting Wood and 4 Bloodvenom Essence to Impsy in Felwood."]="將10塊腐爛的木頭和4個血毒精華交給費伍德森林的伊普斯。",
